[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Merriweather:wght@700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --red-primary: #C41E3A;
      --red-dark: #A01830;
      --navy: #1B3A5C;
      --navy-light: #2A4F7C;
      --white: #FFFFFF;
      --gray-50: #F8F9FA;
      --gray-100: #F1F3F5;
      --gray-200: #E9ECEF;
      --gray-300: #DEE2E6;
      --gray-400: #ADB5BD;
      --gray-500: #6C757D;
      --gray-600: #495057;
      --gray-700: #343A40;
      --gray-800: #212529;
      --gray-900: #1A1A1A;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
      --transition-fast: 150ms ease;
      --transition-base: 250ms ease;
      --transition-slow: 400ms ease;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: var(--gray-800);
      background: var(--white);
      -webkit-font-smoothing: antialiased;
    }

    img {
      max-width: 100%;
      height: auto;
      display: block;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font-family: inherit;
      cursor: pointer;
      border: none;
      background: none;
    }

    .container {
      width: 100%;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    /* Header */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: var(--white);
      box-shadow: var(--shadow-sm);
      border-bottom: 1px solid var(--gray-200);
    }

    .header-top {
      background: var(--navy);
      color: var(--white);
      font-size: 13px;
      padding: 8px 0;
    }

    .header-top-inner {
      display: flex;
      justify-content: flex-end;
      gap: 24px;
    }

    .header-top a {
      opacity: 0.9;
      transition: opacity var(--transition-fast);
    }

    .header-top a:hover {
      opacity: 1;
    }

    .header-main {
      padding: 16px 0;
    }

    .header-main-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 32px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 700;
      font-size: 20px;
      color: var(--navy);
    }

    .logo-icon {
      width: 44px;
      height: 44px;
      background: var(--red-primary);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-weight: 800;
      font-size: 18px;
    }

    .nav-desktop {
      display: none;
    }

    @media (min-width: 1024px) {
      .nav-desktop {
        display: flex;
        align-items: center;
        gap: 8px;
      }
    }

    .nav-link {
      padding: 8px 16px;
      font-size: 15px;
      font-weight: 500;
      color: var(--gray-700);
      border-radius: 6px;
      transition: all var(--transition-fast);
    }

    .nav-link:hover {
      color: var(--navy);
      background: var(--gray-100);
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 24px;
      font-size: 15px;
      font-weight: 600;
      border-radius: 8px;
      transition: all var(--transition-fast);
    }

    .btn-primary {
      background: var(--red-primary);
      color: var(--white);
    }

    .btn-primary:hover {
      background: var(--red-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-secondary {
      background: var(--white);
      color: var(--navy);
      border: 2px solid var(--navy);
    }

    .btn-secondary:hover {
      background: var(--navy);
      color: var(--white);
    }

    .btn-nav-donate {
      background: var(--red-primary);
      color: var(--white);
      padding: 10px 20px;
    }

    .btn-nav-donate:hover {
      background: var(--red-dark);
    }

    .hamburger {
      display: flex;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      border-radius: 6px;
      transition: background var(--transition-fast);
    }

    .hamburger:hover {
      background: var(--gray-100);
    }

    @media (min-width: 1024px) {
      .hamburger {
        display: none;
      }
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--gray-700);
      border-radius: 2px;
      transition: all var(--transition-fast);
    }

    /* Mobile Menu */
    .mobile-menu {
      position: fixed;
      top: 0;
      right: 0;
      bottom: 0;
      width: 320px;
      max-width: 85vw;
      background: var(--white);
      box-shadow: var(--shadow-xl);
      transform: translateX(100%);
      transition: transform var(--transition-base);
      z-index: 200;
      overflow-y: auto;
    }

    .mobile-menu.open {
      transform: translateX(0);
    }

    .mobile-menu-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.5);
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-base);
      z-index: 150;
    }

    .mobile-menu-overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .mobile-menu-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 20px;
      border-bottom: 1px solid var(--gray-200);
    }

    .mobile-menu-close {
      padding: 8px;
      border-radius: 6px;
      transition: background var(--transition-fast);
    }

    .mobile-menu-close:hover {
      background: var(--gray-100);
    }

    .mobile-menu-nav {
      padding: 20px;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .mobile-menu-nav a {
      display: block;
      padding: 12px 16px;
      font-size: 16px;
      font-weight: 500;
      color: var(--gray-700);
      border-radius: 8px;
      transition: all var(--transition-fast);
    }

    .mobile-menu-nav a:hover {
      background: var(--gray-100);
      color: var(--navy);
    }

    .mobile-menu-nav a.nav-donate-mobile {
      background: var(--red-primary);
      color: var(--white);
      text-align: center;
      margin-top: 12px;
    }

    .mobile-menu-nav a.nav-donate-mobile:hover {
      background: var(--red-dark);
    }

    /* Hero */
    .hero {
      background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
      color: var(--white);
      padding: 80px 0 100px;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="40" fill="none" stroke="rgba(255,255,255,0.03)" stroke-width="0.5"/></svg>') repeat;
      background-size: 200px 200px;
    }

    .hero-inner {
      position: relative;
      display: grid;
      gap: 40px;
      align-items: center;
    }

    @media (min-width: 768px) {
      .hero-inner {
        grid-template-columns: 1fr 1fr;
        gap: 60px;
      }
    }

    .hero-content {
      text-align: center;
    }

    @media (min-width: 768px) {
      .hero-content {
        text-align: left;
      }
    }

    .hero-title {
      font-family: 'Merriweather', Georgia, serif;
      font-size: clamp(32px, 5vw, 48px);
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 20px;
    }

    .hero-subtitle {
      font-size: 18px;
      line-height: 1.7;
      opacity: 0.9;
      margin-bottom: 32px;
      max-width: 540px;
    }

    @media (min-width: 768px) {
      .hero-subtitle {
        margin-bottom: 40px;
      }
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 16px;
      justify-content: center;
    }

    @media (min-width: 768px) {
      .hero-actions {
        justify-content: flex-start;
      }
    }

    .hero-visual {
      display: flex;
      justify-content: center;
    }

    .hero-image {
      width: 100%;
      max-width: 480px;
      aspect-ratio: 4/3;
      background: var(--gray-300);
      border-radius: 16px;
      overflow: hidden;
      box-shadow: var(--shadow-xl);
    }

    .hero-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    /* Mission */
    .mission {
      padding: 80px 0;
      background: var(--white);
    }

    .mission-inner {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
    }

    .section-label {
      display: inline-block;
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--red-primary);
      margin-bottom: 16px;
    }

    .section-title {
      font-family: 'Merriweather', Georgia, serif;
      font-size: clamp(28px, 4vw, 36px);
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 24px;
      line-height: 1.3;
    }

    .section-text {
      font-size: 17px;
      line-height: 1.8;
      color: var(--gray-600);
    }

    /* Impact Stats */
    .impact-stats {
      padding: 80px 0;
      background: var(--gray-50);
    }

    .impact-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
    }

    @media (min-width: 768px) {
      .impact-grid {
        grid-template-columns: repeat(4, 1fr);
        gap: 32px;
      }
    }

    .impact-card {
      text-align: center;
      padding: 32px 20px;
      background: var(--white);
      border-radius: 12px;
      box-shadow: var(--shadow-md);
      transition: transform var(--transition-base), box-shadow var(--transition-base);
    }

    .impact-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .impact-number {
      font-size: clamp(36px, 5vw, 48px);
      font-weight: 800;
      color: var(--red-primary);
      line-height: 1;
      margin-bottom: 8px;
    }

    .impact-label {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    /* Programs */
    .programs {
      padding: 80px 0;
      background: var(--white);
    }

    .programs-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .programs-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
      max-width: 800px;
      margin: 0 auto;
    }

    .accordion-item {
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      overflow: hidden;
      transition: box-shadow var(--transition-base);
    }

    .accordion-item:hover {
      box-shadow: var(--shadow-md);
    }

    .accordion-trigger {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 20px 24px;
      background: var(--white);
      font-size: 17px;
      font-weight: 600;
      color: var(--navy);
      text-align: left;
      transition: background var(--transition-fast);
    }

    .accordion-trigger:hover {
      background: var(--gray-50);
    }

    .accordion-icon {
      width: 24px;
      height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform var(--transition-base);
      flex-shrink: 0;
    }

    .accordion-icon svg {
      width: 16px;
      height: 16px;
      stroke: var(--gray-500);
    }

    .accordion-item.open .accordion-icon {
      transform: rotate(180deg);
    }

    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height var(--transition-slow);
    }

    .accordion-item.open .accordion-content {
      max-height: 300px;
    }

    .accordion-body {
      padding: 0 24px 24px;
      color: var(--gray-600);
      line-height: 1.7;
    }

    /* Get Involved */
    .get-involved {
      padding: 80px 0;
      background: var(--navy);
      color: var(--white);
    }

    .get-involved-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .get-involved-header .section-title {
      color: var(--white);
    }

    .get-involved-grid {
      display: grid;
      gap: 24px;
    }

    @media (min-width: 768px) {
      .get-involved-grid {
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
      }
    }

    .involve-card {
      background: rgba(255, 255, 255, 0.08);
      border-radius: 16px;
      padding: 32px 28px;
      text-align: center;
      transition: background var(--transition-base), transform var(--transition-base);
    }

    .involve-card:hover {
      background: rgba(255, 255, 255, 0.12);
      transform: translateY(-4px);
    }

    .involve-icon {
      width: 64px;
      height: 64px;
      margin: 0 auto 20px;
      background: var(--red-primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .involve-icon svg {
      width: 28px;
      height: 28px;
      stroke: var(--white);
    }

    .involve-title {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 12px;
    }

    .involve-text {
      font-size: 15px;
      opacity: 0.85;
      line-height: 1.6;
      margin-bottom: 20px;
    }

    /* News */
    .news {
      padding: 80px 0;
      background: var(--gray-50);
    }

    .news-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 40px;
      flex-wrap: wrap;
      gap: 16px;
    }

    .news-nav-buttons {
      display: flex;
      gap: 8px;
    }

    .news-nav-btn {
      width: 44px;
      height: 44px;
      border-radius: 8px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-fast);
    }

    .news-nav-btn:hover:not(:disabled) {
      background: var(--navy);
      border-color: var(--navy);
      color: var(--white);
    }

    .news-nav-btn:disabled {
      opacity: 0.4;
      cursor: not-allowed;
    }

    .news-nav-btn svg {
      width: 20px;
      height: 20px;
      stroke: currentColor;
    }

    .news-carousel {
      overflow: hidden;
      border-radius: 16px;
    }

    .news-track {
      display: flex;
      transition: transform var(--transition-slow);
    }

    .news-card {
      flex: 0 0 100%;
      padding: 0 12px;
    }

    @media (min-width: 640px) {
      .news-card {
        flex: 0 0 50%;
      }
    }

    @media (min-width: 1024px) {
      .news-card {
        flex: 0 0 25%;
      }
    }

    .news-card-inner {
      background: var(--white);
      border-radius: 12px;
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      height: 100%;
      transition: box-shadow var(--transition-base), transform var(--transition-base);
    }

    .news-card-inner:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-4px);
    }

    .news-image {
      aspect-ratio: 16/10;
      background: var(--gray-300);
      overflow: hidden;
    }

    .news-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .news-content {
      padding: 20px;
    }

    .news-tag {
      display: inline-block;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--red-primary);
      margin-bottom: 8px;
    }

    .news-title {
      font-size: 17px;
      font-weight: 600;
      color: var(--navy);
      line-height: 1.4;
      margin-bottom: 8px;
    }

    .news-excerpt {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* Donate CTA */
    .donate-cta {
      padding: 100px 0;
      background: linear-gradient(135deg, var(--red-primary) 0%, var(--red-dark) 100%);
      color: var(--white);
      text-align: center;
    }

    .donate-cta-inner {
      max-width: 700px;
      margin: 0 auto;
    }

    .donate-cta .section-title {
      color: var(--white);
      font-size: clamp(28px, 4vw, 40px);
    }

    .donate-cta .section-text {
      color: rgba(255, 255, 255, 0.9);
      font-size: 18px;
      margin-bottom: 40px;
    }

    .impact-table {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
      gap: 16px;
      margin-bottom: 40px;
      text-align: left;
    }

    .impact-table-item {
      background: rgba(255, 255, 255, 0.12);
      padding: 16px 20px;
      border-radius: 8px;
    }

    .impact-table-amount {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 4px;
    }

    .impact-table-desc {
      font-size: 13px;
      opacity: 0.85;
    }

    /* Footer */
    .footer {
      background: var(--gray-900);
      color: var(--gray-400);
      padding: 60px 0 30px;
    }

    .footer-grid {
      display: grid;
      gap: 40px;
      margin-bottom: 48px;
    }

    @media (min-width: 640px) {
      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (min-width: 1024px) {
      .footer-grid {
        grid-template-columns: 2fr repeat(3, 1fr);
      }
    }

    .footer-brand {
      max-width: 280px;
    }

    .footer-brand .logo {
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-brand .logo-icon {
      background: var(--red-primary);
    }

    .footer-tagline {
      font-size: 14px;
      line-height: 1.6;
    }

    .footer-col-title {
      font-size: 14px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-links {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-links a {
      font-size: 14px;
      transition: color var(--transition-fast);
    }

    .footer-links a:hover {
      color: var(--white);
    }

    .footer-bottom {
      padding-top: 30px;
      border-top: 1px solid var(--gray-700);
      display: flex;
      flex-direction: column;
      gap: 20px;
      align-items: center;
      text-align: center;
    }

    @media (min-width: 768px) {
      .footer-bottom {
        flex-direction: row;
        justify-content: space-between;
        text-align: left;
      }
    }

    .footer-copyright {
      font-size: 13px;
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--gray-800);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition-fast);
    }

    .footer-social a:hover {
      background: var(--red-primary);
    }

    .footer-social svg {
      width: 18px;
      height: 18px;
      fill: var(--gray-400);
    }

    .footer-social a:hover svg {
      fill: var(--white);
    }

    /* Donate Modal */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.6);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-base);
      z-index: 300;
    }

    .modal-overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .modal {
      background: var(--white);
      border-radius: 20px;
      width: 100%;
      max-width: 480px;
      max-height: 90vh;
      overflow-y: auto;
      transform: scale(0.95) translateY(20px);
      transition: transform var(--transition-base);
    }

    .modal-overlay.open .modal {
      transform: scale(1) translateY(0);
    }

    .modal-header {
      padding: 24px 28px;
      border-bottom: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .modal-title {
      font-size: 22px;
      font-weight: 700;
      color: var(--navy);
    }

    .modal-close {
      width: 36px;
